13	const HELPER = join(ROOT, "web", "components", "LandingData.tsx");
14	const { forwardStarted, landingRows, landingTotals }: {
15	  forwardStarted: (dataDir: string) => boolean;
16	  landingRows: (review: Review) => LandingRow[];
17	  landingTotals: (review: Review) => { sessions: number; spend: string };
18	} = await import(HELPER);
19	const REAL = join(ROOT, "reports", "rajkaria__roster", "review.json");
20	const load = (): Review => JSON.parse(readFileSync(REAL, "utf8"));
21	
22	describe("landingRows", () => {
23	  test("one row per setup, in file order, with sessions and spend from the file", () => {
24	    const review = load();
25	    const rows = landingRows(review);
26	    expect(rows.length).toBe(review.setups.length);
27	    rows.forEach((r, i) => {
28	      const s = review.setups[i]!;
29	      expect(r.setup_id).toBe(s.setup_id);
30	      expect(r.label).toBe(s.label);
31	      expect(r.sessions).toBe(s.sessions);
