33	      else expect(r.spend).toBe(`${s.spend_lower_bound ? "≥ " : ""}$${s.spend_usd.toFixed(2)}`);
34	      if (s.mature_sessions === 0) expect(r.unattended).toBe("too young");
35	    });
36	  });
37	
38	  test("unknown spend is never shown as $0", () => {
39	    const review = load();
40	    const s = { ...review.setups[0]!, spend_usd: null, priced_sessions: 1, sessions: 3 };
41	    const [row] = landingRows({ ...review, setups: [s] });
42	    expect(row!.spend).toBe("unknown (1/3 priced)");
43	    expect(landingTotals({ ...review, setups: [s, ...review.setups.slice(1)] }).spend).toStartWith("unknown");
44	  });
45	
46	  test("mature setups show unattended as a percentage", () => {
47	    const review = load();
48	    const s = { ...review.setups[0]!, mature_sessions: 4, unattended: 0.25 };
49	    expect(landingRows({ ...review, setups: [s] })[0]!.unattended).toBe("25%");
50	  });
51	});
52	
53	describe("landingTotals", () => {
